insert into public.questions (id, kind, prompt, options, marks, image_url) values ('954f0fe9-5f9d-5d28-a2bd-5d8ee4fbf71d', 'short', '3. State what these conditions may have caused to happen to simple inorganic molecules.', '[]'::jsonb, 1, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('954f0fe9-5f9d-5d28-a2bd-5d8ee4fbf71d', 'They may have caused a variety of carbon compounds (amino acids, sugars, fatty acids, bases) to form spontaneously from simple inorganic molecules, without any living organism.', 'They may have caused a variety of carbon compounds (amino acids, sugars, fatty acids, bases) to form spontaneously from simple inorganic molecules, without any living organism.', '[{"text": "Marking point 1", "any": ["carbon compound", "organic", "amino acid", "sugar"], "all": [], "marks": 1}]'::jsonb, 'They may have caused a variety of carbon compounds (amino acids, sugars, fatty acids, bases) to form spontaneously from simple inorganic molecules, without any living organism.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
