insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('560d70d5-c7d7-54ea-b39f-e43247585440', 'A sealed glass apparatus; water heated so vapour circulated (the ocean and evaporation); vapour passed into a flask of methane, ammonia and hydrogen with no oxygen (the early atmosphere); continuous sparks between tungsten electrodes (lightning); gases cooled in a condenser and fell as "rain" into a U-shaped trap and back to the water flask; ran for about a week; samples analysed by paper chromatography.', 'A sealed glass apparatus; water heated so vapour circulated (the ocean and evaporation); vapour passed into a flask of methane, ammonia and hydrogen with no oxygen (the early atmosphere); continuous sparks between tungsten electrodes (lightning); gases cooled in a condenser and fell as "rain" into a U-shaped trap and back to the water flask; ran for about a week; samples analysed by paper chromatography.', '[{"text": "Marking point 1", "any": ["ocean", "vapour", "vapor"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["methane", "ammonia", "hydrogen", "gas mixture", "no oxygen"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["spark", "electrod", "lightning"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["condens", "cool", "rain"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["week", "sample", "analys", "chromatograph", "trap"], "all": [], "marks": 1}]'::jsonb, 'A sealed glass apparatus; water heated so vapour circulated (the ocean and evaporation); vapour passed into a flask of methane, ammonia and hydrogen with no oxygen (the early atmosphere); continuous sparks between tungsten electrodes (lightning); gases cooled in a condenser and fell as "rain" into a U-shaped trap and back to the water flask; ran for about a week; samples analysed by paper chromatography.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
