insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fb090ba2-d244-5398-9187-54d26e2665a8', 'short', '6. State the results, and the conclusion that can be drawn from them.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('fb090ba2-d244-5398-9187-54d26e2665a8', 'Results: the solution turned pink then brown; several amino acids (glycine, alanine) and other organic compounds formed (re-analysis later found over twenty amino acids). Conclusion: biologically relevant carbon compounds can form spontaneously from inorganic molecules under early-Earth-like conditions with an energy source, so life''s building blocks could have arisen before life. It does not show that this is how life happened.', 'Results: the solution turned pink then brown; several amino acids (glycine, alanine) and other organic compounds formed (re-analysis later found over twenty amino acids). Conclusion: biologically relevant carbon compounds can form spontaneously from inorganic molecules under early-Earth-like conditions with an energy source, so life''s building blocks could have arisen before life. It does not show that this is how life happened.', '[{"text": "Marking point 1", "any": ["amino acid", "glycine", "alanine", "organic"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["could form", "can form", "spontaneous", "inorganic", "possible", "building blocks"], "all": [], "marks": 1}]'::jsonb, 'Results: the solution turned pink then brown; several amino acids (glycine, alanine) and other organic compounds formed (re-analysis later found over twenty amino acids). Conclusion: biologically relevant carbon compounds can form spontaneously from inorganic molecules under early-Earth-like conditions with an energy source, so life''s building blocks could have arisen before life. It does not show that this is how life happened.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('baa83eed-9aeb-5b33-8e07-8e69b23e43ff', 'fb090ba2-d244-5398-9187-54d26e2665a8', 7);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c66c4809-8dd2-5199-904f-90c9f209221b', 'short', '7. Discuss the benefits and limitations of the Miller–Urey apparatus as a model of a natural phenomenon. Add at least two more benefits and two more limitations of your own.', '[]'::jsonb, 4, 'https://biosciencevista.com/assets/quizimg/018521ade7c6cdd0.jpg') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c66c4809-8dd2-5199-904f-90c9f209221b', 'Benefits: safe, small-scale and cheap; runs in days rather than millions of years; can be modified to compare hypotheses; products accumulate for analysis; shows a step is chemically possible. Limitations: a closed few-litre system cannot represent an open ocean; one week cannot represent hundreds of millions of years; products sheltered in glass from UV; products concentrated rather than diluted; continuous rather than occasional sparking; amino acids are not life (no polymers, no self-replication, racemic); shows what could happen, not what did.', 'Benefits: safe, small-scale and cheap; runs in days rather than millions of years; can be modified to compare hypotheses; products accumulate for analysis; shows a step is chemically possible. Limitations: a closed few-litre system cannot represent an open ocean; one week cannot represent hundreds of millions of years; products sheltered in glass from UV; products concentrated rather than diluted; continuous rather than occasional sparking; amino acids are not life (no polymers, no self-replication, racemic); shows what could happen, not what did.', '[{"text": "Marking point 1", "any": ["safe", "small scale", "cheap", "inexpensive", "cost"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["days", "quick", "fast", "modif", "different gases", "sample", "possible"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["closed", "scale", "volume", "week", "timescale", "million"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["glass", "protect", " uv ", "diluted", "concentrat", "continuous", "not life", "polymer", "did happen", "racemic"], "all": [], "marks": 1}]'::jsonb, 'Benefits: safe, small-scale and cheap; runs in days rather than millions of years; can be modified to compare hypotheses; products accumulate for analysis; shows a step is chemically possible. Limitations: a closed few-litre system cannot represent an open ocean; one week cannot represent hundreds of millions of years; products sheltered in glass from UV; products concentrated rather than diluted; continuous rather than occasional sparking; amino acids are not life (no polymers, no self-replication, racemic); shows what could happen, not what did.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('baa83eed-9aeb-5b33-8e07-8e69b23e43ff', 'c66c4809-8dd2-5199-904f-90c9f209221b', 8);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2e8a36e6-a65d-50e5-b359-7187918874cb', 'short', '8. Outline the cause of the spontaneous formation of vesicles by amphipathic molecules.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2e8a36e6-a65d-50e5-b359-7187918874cb', 'Fatty acids and phospholipids are amphipathic (hydrophilic head, hydrophobic tails); in water the tails are excluded, so the molecules arrange with tails shielded and heads facing the water; this is the more stable arrangement, so it forms spontaneously with no energy, enzymes or genetic information; a bilayer closes into a sphere to remove its exposed edge.', 'Fatty acids and phospholipids are amphipathic (hydrophilic head, hydrophobic tails); in water the tails are excluded, so the molecules arrange with tails shielded and heads facing the water; this is the more stable arrangement, so it forms spontaneously with no energy, enzymes or genetic information; a bilayer closes into a sphere to remove its exposed edge.', '[{"text": "Marking point 1", "any": ["amphipathic"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["heads face", "excluded"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["stable", "no energy", "spontaneous", "no enzyme", "edge", "sphere"], "all": [], "marks": 1}]'::jsonb, 'Fatty acids and phospholipids are amphipathic (hydrophilic head, hydrophobic tails); in water the tails are excluded, so the molecules arrange with tails shielded and heads facing the water; this is the more stable arrangement, so it forms spontaneously with no energy, enzymes or genetic information; a bilayer closes into a sphere to remove its exposed edge.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('baa83eed-9aeb-5b33-8e07-8e69b23e43ff', '2e8a36e6-a65d-50e5-b359-7187918874cb', 9);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('03569e10-407c-5039-8934-a54d55518fd9', 'short', '9. Outline the consequence of vesicle formation for the origin of the first cells.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('03569e10-407c-5039-8934-a54d55518fd9', 'The vesicle encloses water, creating an internal environment separate from the surroundings; molecules can be concentrated and a self-replicating molecule kept with its products, so the compartment can be selected as a unit; vesicles can grow and divide; this compartmentalisation produces a protocell.', 'The vesicle encloses water, creating an internal environment separate from the surroundings; molecules can be concentrated and a self-replicating molecule kept with its products, so the compartment can be selected as a unit; vesicles can grow and divide; this compartmentalisation produces a protocell.', '[{"text": "Marking point 1", "any": ["internal environment", "inside", "separate", "enclos"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["concentrat", "together", "products", "replicat", "selected"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["grow", "divide", "protocell", "compartment"], "all": [], "marks": 1}]'::jsonb, 'The vesicle encloses water, creating an internal environment separate from the surroundings; molecules can be concentrated and a self-replicating molecule kept with its products, so the compartment can be selected as a unit; vesicles can grow and divide; this compartmentalisation produces a protocell.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('baa83eed-9aeb-5b33-8e07-8e69b23e43ff', '03569e10-407c-5039-8934-a54d55518fd9', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a4d78381-cecc-54c5-af9a-e747835e3c85', 'mcq', '10. Put the intermediate stages needed for the evolution of the first cells in the right order.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a4d78381-cecc-54c5-af9a-e747835e3c85', 1, '1 simple organic molecules from inorganic ones; 2 monomers join into polymers; 3 self-replicating molecules (RNA) appear; 4 they are enclosed in vesicles (protocells); 5 DNA takes over information storage and proteins catalysis: the first true cells.', 'Simple organic molecules form from inorganic molecules') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
