insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3a509714-0f3b-5492-a157-16a421ed6344', 'short', '11. Discuss the limitations in testing hypotheses about the evolution of the first cells.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3a509714-0f3b-5492-a157-16a421ed6344', 'The events were about four billion years ago with no direct record of the intermediate stages; rocks of that age are destroyed or altered by tectonics, metamorphism and erosion; the earliest microfossils are contested (biological or mineral?); experiments cannot reproduce an ocean or hundreds of millions of years; the early atmosphere is uncertain; chance events cannot be re-run. Above all, an experiment shows a step is possible, not that it actually occurred.', 'The events were about four billion years ago with no direct record of the intermediate stages; rocks of that age are destroyed or altered by tectonics, metamorphism and erosion; the earliest microfossils are contested (biological or mineral?); experiments cannot reproduce an ocean or hundreds of millions of years; the early atmosphere is uncertain; chance events cannot be re-run. Above all, an experiment shows a step is possible, not that it actually occurred.', '[{"text": "Marking point 1", "any": ["billion", "long ago", "no direct record", "no record"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["tectonic", "erosion", "metamorph"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["microfossil", "contested", "mineral"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["scale", "timescale", "reproduce", "atmosphere", "chance", "repeat"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["possible", "actually", "did happen", "what happened"], "all": [], "marks": 1}]'::jsonb, 'The events were about four billion years ago with no direct record of the intermediate stages; rocks of that age are destroyed or altered by tectonics, metamorphism and erosion; the earliest microfossils are contested (biological or mineral?); experiments cannot reproduce an ocean or hundreds of millions of years; the early atmosphere is uncertain; chance events cannot be re-run. Above all, an experiment shows a step is possible, not that it actually occurred.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('baa83eed-9aeb-5b33-8e07-8e69b23e43ff', '3a509714-0f3b-5492-a157-16a421ed6344', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('89d392d2-28b8-5529-8df2-063a62931d39', 'short', '12. Discuss the challenges of defining matter as living or non-living.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('89d392d2-28b8-5529-8df2-063a62931d39', 'There is no single agreed definition; definitions are lists of characteristics with exceptions (a mule cannot reproduce, a red blood cell cannot divide, a dormant seed or tardigrade barely metabolises); non-living things share some characteristics (fire grows and uses fuel; crystals grow); life arose gradually from chemistry, so there is no sharp boundary, which is why borderline cases such as viruses are hard to place.', 'There is no single agreed definition; definitions are lists of characteristics with exceptions (a mule cannot reproduce, a red blood cell cannot divide, a dormant seed or tardigrade barely metabolises); non-living things share some characteristics (fire grows and uses fuel; crystals grow); life arose gradually from chemistry, so there is no sharp boundary, which is why borderline cases such as viruses are hard to place.', '[{"text": "Marking point 1", "any": ["no single", "no agreed", "list", "characteristics", "exception"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["mule", "red blood cell", "seed", "tardigrade", "fire", "crystal"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["gradual", "continuum", "boundary", "virus"], "all": [], "marks": 1}]'::jsonb, 'There is no single agreed definition; definitions are lists of characteristics with exceptions (a mule cannot reproduce, a red blood cell cannot divide, a dormant seed or tardigrade barely metabolises); non-living things share some characteristics (fire grows and uses fuel; crystals grow); life arose gradually from chemistry, so there is no sharp boundary, which is why borderline cases such as viruses are hard to place.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('baa83eed-9aeb-5b33-8e07-8e69b23e43ff', '89d392d2-28b8-5529-8df2-063a62931d39', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('78345d1c-93e3-5d5f-9a16-8c7bfb0a718a', 'short', '13(a). Give reasons cells are considered LIVING.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('78345d1c-93e3-5d5f-9a16-8c7bfb0a718a', 'A cell carries out all the functions of life with its own machinery; has its own metabolism (enzymes); is bounded by a membrane and maintains an internal environment (homeostasis); stores its own genetic information and replicates; is self-sustaining.', 'A cell carries out all the functions of life with its own machinery; has its own metabolism (enzymes); is bounded by a membrane and maintains an internal environment (homeostasis); stores its own genetic information and replicates; is self-sustaining.', '[{"text": "Marking point 1", "any": ["all the functions", "functions of life", "metabol", "enzyme"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["membrane", "homeostasis", "replicat", "divide", "self sustaining", "genetic", "reproduce"], "all": [], "marks": 1}]'::jsonb, 'A cell carries out all the functions of life with its own machinery; has its own metabolism (enzymes); is bounded by a membrane and maintains an internal environment (homeostasis); stores its own genetic information and replicates; is self-sustaining.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('baa83eed-9aeb-5b33-8e07-8e69b23e43ff', '78345d1c-93e3-5d5f-9a16-8c7bfb0a718a', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fe2f30ed-8a90-579d-8463-0f5826d6ae36', 'short', '13(b). Give reasons viruses are considered NON-LIVING.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('fe2f30ed-8a90-579d-8463-0f5826d6ae36', 'A virus carries out none of the functions of life on its own and has no metabolism; it has no cytoplasm or cell structure (inert outside a host, can be crystallised); it can only be replicated using a host cell''s ribosomes, enzymes and nucleotides; it does not grow, respond or show homeostasis.', 'A virus carries out none of the functions of life on its own and has no metabolism; it has no cytoplasm or cell structure (inert outside a host, can be crystallised); it can only be replicated using a host cell''s ribosomes, enzymes and nucleotides; it does not grow, respond or show homeostasis.', '[{"text": "Marking point 1", "any": ["no metabol", "none of the functions", "no enzyme", "cannot carry out", "no functions"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["host", "cannot reproduce", "can t reproduce", "independently", "crystal", "inert", "no cytoplasm", "no cell", "not grow", "no homeostasis"], "all": [], "marks": 1}]'::jsonb, 'A virus carries out none of the functions of life on its own and has no metabolism; it has no cytoplasm or cell structure (inert outside a host, can be crystallised); it can only be replicated using a host cell''s ribosomes, enzymes and nucleotides; it does not grow, respond or show homeostasis.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('baa83eed-9aeb-5b33-8e07-8e69b23e43ff', 'fe2f30ed-8a90-579d-8463-0f5826d6ae36', 17);
