insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d36e99b8-d475-5ff5-8a9a-27af135e153a', 'mcq', 'For each need, what does the virus use from the host cell?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('d36e99b8-d475-5ff5-8a9a-27af135e153a', 1, 'Energy: ATP from the host''s respiration. Nucleic acid: host nucleotides. Proteins: host amino acids, made on host ribosomes with host tRNA.', 'nucleotides') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', 'd36e99b8-d475-5ff5-8a9a-27af135e153a', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('340aeb43-6849-5fa2-a84f-dd261c6752c4', 'short', 'Explain why viruses cannot reproduce independently.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('340aeb43-6849-5fa2-a84f-dd261c6752c4', 'Viruses have no cytoplasm, ribosomes or metabolism, so they cannot make proteins [1]; they cannot make ATP or obtain nucleotides and amino acids [1]; so they must use the machinery of a host cell: they are obligate parasites [1].', 'Viruses have no cytoplasm, ribosomes or metabolism, so they cannot make proteins [1]; they cannot make ATP or obtain nucleotides and amino acids [1]; so they must use the machinery of a host cell: they are obligate parasites [1].', '[{"text": "Marking point 1", "any": ["no cytoplasm", "no ribosome", "no metabolism", "cannot make protein", "no enzyme"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["atp", "energy"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["host", "obligate", "parasite"], "all": [], "marks": 1}]'::jsonb, 'Viruses have no cytoplasm, ribosomes or metabolism, so they cannot make proteins [1]; they cannot make ATP or obtain nucleotides and amino acids [1]; so they must use the machinery of a host cell: they are obligate parasites [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '340aeb43-6849-5fa2-a84f-dd261c6752c4', 6);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('87acd7d4-281f-51c0-830b-904cfd7571c8', 'short', 'Explain why a virus''s genes can be expressed by a host cell from a completely different organism.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('87acd7d4-281f-51c0-830b-904cfd7571c8', 'The genetic code is shared (universal) [1], so the host''s ribosomes and tRNAs translate viral codons into the same amino acids as intended and make viral proteins [1].', 'The genetic code is shared (universal) [1], so the host''s ribosomes and tRNAs translate viral codons into the same amino acids as intended and make viral proteins [1].', '[{"text": "Marking point 1", "any": ["genetic code", "universal", "same code", "same codons"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ribosome", "translat", "amino acid"], "all": [], "marks": 1}]'::jsonb, 'The genetic code is shared (universal) [1], so the host''s ribosomes and tRNAs translate viral codons into the same amino acids as intended and make viral proteins [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
