insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5dffcd3c-de3d-5388-b503-169a97a37029', 'short', 'Distinguish between positive-sense and negative-sense RNA viruses.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5dffcd3c-de3d-5388-b503-169a97a37029', 'The genome of a positive-sense virus acts as mRNA and is translated directly by host ribosomes [1]; a negative-sense genome must first be copied into a complementary (positive) strand by a viral RNA polymerase before it can be translated [1].', 'The genome of a positive-sense virus acts as mRNA and is translated directly by host ribosomes [1]; a negative-sense genome must first be copied into a complementary (positive) strand by a viral RNA polymerase before it can be translated [1].', '[{"text": "Marking point 1", "any": ["positive", "directly", "mrna", "translated"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["negative", "complementary", "copied", "polymerase", "first"], "all": [], "marks": 1}]'::jsonb, 'The genome of a positive-sense virus acts as mRNA and is translated directly by host ribosomes [1]; a negative-sense genome must first be copied into a complementary (positive) strand by a viral RNA polymerase before it can be translated [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '5dffcd3c-de3d-5388-b503-169a97a37029', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f144d61f-f5a5-5683-b234-fcceff4d1d57', 'mcq', 'Which virus does each statement describe?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f144d61f-f5a5-5683-b234-fcceff4d1d57', 2, 'Lambda: dsDNA, infects bacteria, not enveloped. Coronavirus: spike proteins bind ACE2. HIV: reverse transcriptase, infects helper (CD4) T cells.', 'HIV') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', 'f144d61f-f5a5-5683-b234-fcceff4d1d57', 12);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ac8b7eea-4a42-5bd0-a1cb-4b58ca314995', 'short', 'Outline the role of reverse transcriptase in HIV.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ac8b7eea-4a42-5bd0-a1cb-4b58ca314995', 'Reverse transcriptase uses the viral RNA as a template [1] to make DNA, which is then inserted into the host cell''s DNA [1].', 'Reverse transcriptase uses the viral RNA as a template [1] to make DNA, which is then inserted into the host cell''s DNA [1].', '[{"text": "Marking point 1", "any": ["rna"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["dna"], "all": [], "marks": 1}]'::jsonb, 'Reverse transcriptase uses the viral RNA as a template [1] to make DNA, which is then inserted into the host cell''s DNA [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
