insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b62a74a1-bafd-5c6b-8e59-113ca4e2e357', 'mcq', 'Why can soap destroy SARS-CoV-2 but not bacteriophage lambda?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('b62a74a1-bafd-5c6b-8e59-113ca4e2e357', 1, 'The coronavirus envelope is a phospholipid membrane, which detergents dissolve. Lambda has only a protein capsid.', 'Soap dissolves the lipid envelope; lambda has no envelope') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', 'b62a74a1-bafd-5c6b-8e59-113ca4e2e357', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('705b6537-5f41-5161-b1a7-7fba2dbfeb5b', 'short', 'Explain why an RNA virus must carry or encode its own RNA polymerase.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('705b6537-5f41-5161-b1a7-7fba2dbfeb5b', 'Host cells only make RNA from a DNA template [1], so they have no enzyme to copy the viral RNA genome; the virus must supply an RNA-dependent RNA polymerase [1].', 'Host cells only make RNA from a DNA template [1], so they have no enzyme to copy the viral RNA genome; the virus must supply an RNA-dependent RNA polymerase [1].', '[{"text": "Marking point 1", "any": ["host", "cell"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["cannot", "do not", "no enzyme", "rna from rna", "rna template"], "all": [], "marks": 1}]'::jsonb, 'Host cells only make RNA from a DNA template [1], so they have no enzyme to copy the viral RNA genome; the virus must supply an RNA-dependent RNA polymerase [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '705b6537-5f41-5161-b1a7-7fba2dbfeb5b', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f418edeb-1d51-57da-8dfb-2bc38da35a0d', 'short', 'Compare the structures of bacteriophage lambda, coronavirus and HIV. [4]', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f418edeb-1d51-57da-8dfb-2bc38da35a0d', 'All three have a protein capsid surrounding their nucleic acid [1]. Lambda has dsDNA while coronavirus and HIV have ssRNA [1]. Coronavirus and HIV are enveloped with surface glycoproteins; lambda is not enveloped [1]. Lambda has an icosahedral head and tail; coronavirus a helical nucleocapsid with spikes; HIV a cone-shaped capsid containing reverse transcriptase [1].', 'All three have a protein capsid surrounding their nucleic acid [1]. Lambda has dsDNA while coronavirus and HIV have ssRNA [1]. Coronavirus and HIV are enveloped with surface glycoproteins; lambda is not enveloped [1]. Lambda has an icosahedral head and tail; coronavirus a helical nucleocapsid with spikes; HIV a cone-shaped capsid containing reverse transcriptase [1].', '[{"text": "Marking point 1", "any": ["dna", "double"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["rna"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["envelope", "enveloped"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["tail", "capsid", "spike", "reverse transcriptase", "icosahedral", "helical"], "all": [], "marks": 1}]'::jsonb, 'All three have a protein capsid surrounding their nucleic acid [1]. Lambda has dsDNA while coronavirus and HIV have ssRNA [1]. Coronavirus and HIV are enveloped with surface glycoproteins; lambda is not enveloped [1]. Lambda has an icosahedral head and tail; coronavirus a helical nucleocapsid with spikes; HIV a cone-shaped capsid containing reverse transcriptase [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', 'f418edeb-1d51-57da-8dfb-2bc38da35a0d', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('136f7aa2-bed4-5607-9e04-47bd9c2add91', 'mcq', 'Put the phases in order.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('136f7aa2-bed4-5607-9e04-47bd9c2add91', 3, 'Attachment → injection → replication and protein synthesis → assembly → lysis.', 'Assembly') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '136f7aa2-bed4-5607-9e04-47bd9c2add91', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('228d7761-1395-5069-89f6-f16d3c44fd69', 'mcq', 'Match each event to its phase.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('228d7761-1395-5069-89f6-f16d3c44fd69', 1, 'Receptor binding: attachment. Capsid outside: injection. Ribosomes make proteins: synthesis. Heads filled: assembly. Wall broken down: lysis.', 'Injection') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '228d7761-1395-5069-89f6-f16d3c44fd69', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7291f58d-ca1b-5956-b400-64641791fd09', 'short', 'Explain why the phage needs a specific receptor on the host cell.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7291f58d-ca1b-5956-b400-64641791fd09', 'The tail fibre has a shape complementary to a particular receptor protein [1], so the phage can only attach to and infect cells that carry it (here E. coli): this decides its host range [1].', 'The tail fibre has a shape complementary to a particular receptor protein [1], so the phage can only attach to and infect cells that carry it (here E. coli): this decides its host range [1].', '[{"text": "Marking point 1", "any": ["specific", "shape", "complementary", "bind"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["only", "host range", "particular", "e. coli", "which cell"], "all": [], "marks": 1}]'::jsonb, 'The tail fibre has a shape complementary to a particular receptor protein [1], so the phage can only attach to and infect cells that carry it (here E. coli): this decides its host range [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '7291f58d-ca1b-5956-b400-64641791fd09', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0bd7c7be-7bad-579f-bf26-d60798306ee7', 'short', 'Why does the host cell die in the lytic cycle?', '[]'::jsonb, 1, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0bd7c7be-7bad-579f-bf26-d60798306ee7', 'Viral enzymes break down the cell wall and the cell bursts (lysis) to release the new phages.', 'Viral enzymes break down the cell wall and the cell bursts (lysis) to release the new phages.', '[{"text": "Marking point 1", "any": ["burst", "lysis", "wall", "break"], "all": [], "marks": 1}]'::jsonb, 'Viral enzymes break down the cell wall and the cell bursts (lysis) to release the new phages.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '0bd7c7be-7bad-579f-bf26-d60798306ee7', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fcc916cd-4b79-5eba-9f77-9579288558ad', 'short', 'Explain how bacteriophage lambda relies on its host cell for replication.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('fcc916cd-4b79-5eba-9f77-9579288558ad', 'The host supplies ATP from respiration for every energy-requiring step [1]; nucleotides to copy the phage DNA and amino acids for its proteins [1]; and ribosomes, tRNA and enzymes to transcribe and translate the viral genes [1].', 'The host supplies ATP from respiration for every energy-requiring step [1]; nucleotides to copy the phage DNA and amino acids for its proteins [1]; and ribosomes, tRNA and enzymes to transcribe and translate the viral genes [1].', '[{"text": "Marking point 1", "any": ["atp", "energy"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["nucleotide", "amino acid"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["ribosome", "enzyme", "trna", "protein synthesis"], "all": [], "marks": 1}]'::jsonb, 'The host supplies ATP from respiration for every energy-requiring step [1]; nucleotides to copy the phage DNA and amino acids for its proteins [1]; and ribosomes, tRNA and enzymes to transcribe and translate the viral genes [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', 'fcc916cd-4b79-5eba-9f77-9579288558ad', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('27c22d91-c8b7-5252-b869-76c067dcbe7d', 'mcq', 'Which part of phage lambda does NOT enter the host cell?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('27c22d91-c8b7-5252-b869-76c067dcbe7d', 1, 'The protein capsid (head and tail) stays outside; only the DNA is injected.', 'Its protein capsid') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '27c22d91-c8b7-5252-b869-76c067dcbe7d', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('494ad0d7-ac1f-5e6e-a12b-fa8e4b6fb8d5', 'mcq', 'Put the lysogenic cycle in order.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('494ad0d7-ac1f-5e6e-a12b-fa8e4b6fb8d5', 2, 'Attachment → injection → integration (prophage) → copied at each cell division → induction → lytic cycle.', 'Integration as a prophage') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '494ad0d7-ac1f-5e6e-a12b-fa8e4b6fb8d5', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('86d95306-d6a3-5fa8-a384-33eae572cb40', 'mcq', 'Lytic, lysogenic or both?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('86d95306-d6a3-5fa8-a384-33eae572cb40', 0, 'Both: injection. Lytic: lysis, assembly of many phages. Lysogenic: prophage, passed to daughter cells, host survives.', 'Lytic') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '86d95306-d6a3-5fa8-a384-33eae572cb40', 24);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('40858a4f-d16d-533a-ac8f-7ccd90003272', 'mcq', 'Lytic, lysogenic or both?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('40858a4f-d16d-533a-ac8f-7ccd90003272', 1, 'Both: injection. Lytic: lysis, assembly of many phages. Lysogenic: prophage, passed to daughter cells, host survives.', 'Lysogenic') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '40858a4f-d16d-533a-ac8f-7ccd90003272', 25);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8236b95f-2e2c-5f60-9eb3-212456379464', 'mcq', 'Which hypothesis does each statement support?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8236b95f-2e2c-5f60-9eb3-212456379464', 1, 'Plasmid-like genes support escape. Giant viruses with translation-related genes, and loss of metabolic genes, support reduction.', 'Regressive (reduction)') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '8236b95f-2e2c-5f60-9eb3-212456379464', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('06dad1a1-95ec-58f4-9646-8b737e7c7602', 'mcq', 'Drift or shift?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('06dad1a1-95ec-58f4-9646-8b737e7c7602', 0, 'Drift: gradual point mutations, yearly vaccine updates. Shift: reassortment, new subtype, can start a pandemic.', 'Antigenic drift') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('de75440e-ce28-543a-9d68-74718dd7a06c', '06dad1a1-95ec-58f4-9646-8b737e7c7602', 27);
