insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cbb829db-ed77-5982-93ca-213c298722e4', 'Phospholipids are amphipathic: a hydrophilic head and hydrophobic tails [1]; the heads are attracted to water so face the water on both sides [1]; the tails are repelled by water so point inwards towards each other, forming the core [1].', 'Phospholipids are amphipathic: a hydrophilic head and hydrophobic tails [1]; the heads are attracted to water so face the water on both sides [1]; the tails are repelled by water so point inwards towards each other, forming the core [1].', '[{"text": "Marking point 1", "any": ["amphipathic"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["heads face", "heads towards", "heads outward", "heads on the outside"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["tails inward", "tails face each other", "tails point in", "tails in the middle", "tails inside", "inward", "core", "middle"], "all": [], "marks": 1}]'::jsonb, 'Phospholipids are amphipathic: a hydrophilic head and hydrophobic tails [1]; the heads are attracted to water so face the water on both sides [1]; the tails are repelled by water so point inwards towards each other, forming the core [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
