insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b2bee657-bfa2-5cdf-9463-93c699b1f367', 'short', 'Distinguish between facilitated diffusion and active transport.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b2bee657-bfa2-5cdf-9463-93c699b1f367', 'Facilitated diffusion moves particles down the concentration gradient (high to low) [1]; active transport moves them against the gradient (low to high) [1]; active transport uses energy from ATP, facilitated diffusion does not [1]. (Both use specific membrane proteins: channels or pumps.)', 'Facilitated diffusion moves particles down the concentration gradient (high to low) [1]; active transport moves them against the gradient (low to high) [1]; active transport uses energy from ATP, facilitated diffusion does not [1]. (Both use specific membrane proteins: channels or pumps.)', '[{"text": "Marking point 1", "any": ["high to low", "higher to lower"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["against", "up the gradient", "low to high", "lower to higher"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["atp", "energy"], "all": [], "marks": 1}]'::jsonb, 'Facilitated diffusion moves particles down the concentration gradient (high to low) [1]; active transport moves them against the gradient (low to high) [1]; active transport uses energy from ATP, facilitated diffusion does not [1]. (Both use specific membrane proteins: channels or pumps.)') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('add5f177-be81-55cd-ade0-e128fe434315', 'b2bee657-bfa2-5cdf-9463-93c699b1f367', 14);
