insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3ee9b352-e626-51eb-bec6-e75146b25eb4', 'short', 'Explain how the structure of a cell membrane makes it selectively permeable.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3ee9b352-e626-51eb-bec6-e75146b25eb4', 'The bilayer has a hydrophobic core [1] that ions, polar and large molecules cannot easily cross, while small non-polar molecules diffuse through [1]; channel and pump proteins transport particles across [1]; each protein is specific to particular particles, so only selected substances pass [1].', 'The bilayer has a hydrophobic core [1] that ions, polar and large molecules cannot easily cross, while small non-polar molecules diffuse through [1]; channel and pump proteins transport particles across [1]; each protein is specific to particular particles, so only selected substances pass [1].', '[{"text": "Marking point 1", "any": ["hydrophobic", "non-polar core", "lipid core"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ions", "polar", "large molecules", "charged"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["channel", "pump", "transport protein", "carrier"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["specific", "particular", "only certain"], "all": [], "marks": 1}]'::jsonb, 'The bilayer has a hydrophobic core [1] that ions, polar and large molecules cannot easily cross, while small non-polar molecules diffuse through [1]; channel and pump proteins transport particles across [1]; each protein is specific to particular particles, so only selected substances pass [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('add5f177-be81-55cd-ade0-e128fe434315', '3ee9b352-e626-51eb-bec6-e75146b25eb4', 16);
