insert into public.questions (id, kind, prompt, options, marks, image_url) values ('af6eba8f-4a6d-5897-b860-629b52079052', 'short', 'Explain why fish living in cold water have a higher proportion of unsaturated fatty acids in their membranes.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('af6eba8f-4a6d-5897-b860-629b52079052', 'Unsaturated fatty acids have C=C double bonds that kink the tails [1]; so they cannot pack tightly and have a lower melting point [1]; the membrane stays fluid and flexible at low temperature, so proteins and vesicles keep working [1].', 'Unsaturated fatty acids have C=C double bonds that kink the tails [1]; so they cannot pack tightly and have a lower melting point [1]; the membrane stays fluid and flexible at low temperature, so proteins and vesicles keep working [1].', '[{"text": "Marking point 1", "any": ["kink", "double bond", "bent", "c=c"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["loose", "cannot pack", "less tightly", "lower melting"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["fluid", "flexible"], "all": [], "marks": 1}]'::jsonb, 'Unsaturated fatty acids have C=C double bonds that kink the tails [1]; so they cannot pack tightly and have a lower melting point [1]; the membrane stays fluid and flexible at low temperature, so proteins and vesicles keep working [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
