insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('618b5821-39f6-59c8-8c28-e711ef33073d', 'The vesicle moves to and fuses with the plasma membrane, releasing its contents outside [1]; this is possible because the phospholipids are fluid and can move and rejoin into one continuous membrane [1].', 'The vesicle moves to and fuses with the plasma membrane, releasing its contents outside [1]; this is possible because the phospholipids are fluid and can move and rejoin into one continuous membrane [1].', '[{"text": "Marking point 1", "any": ["fuses", "fusion", "merge"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fluid", "phospholipids move", "flexible", "reseal", "join"], "all": [], "marks": 1}]'::jsonb, 'The vesicle moves to and fuses with the plasma membrane, releasing its contents outside [1]; this is possible because the phospholipids are fluid and can move and rejoin into one continuous membrane [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
