insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0939157e-2b6d-526f-9e81-f554572786ac', 'short', 'Explain how the sodium–potassium pump contributes to the resting potential of a neuron.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0939157e-2b6d-526f-9e81-f554572786ac', 'The pump moves 3 Na⁺ out for every 2 K⁺ in [1], using ATP to move both ions against their gradients (active transport) [1]; so more positive charge leaves than enters, making the inside negative relative to the outside: a membrane potential [1].', 'The pump moves 3 Na⁺ out for every 2 K⁺ in [1], using ATP to move both ions against their gradients (active transport) [1]; so more positive charge leaves than enters, making the inside negative relative to the outside: a membrane potential [1].', '[{"text": "Marking point 1", "any": ["more positive out", "more na out"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["atp", "active transport", "against"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["negative inside", "inside negative", "charge difference", "potential difference", "polarised"], "all": [], "marks": 1}]'::jsonb, 'The pump moves 3 Na⁺ out for every 2 K⁺ in [1], using ATP to move both ions against their gradients (active transport) [1]; so more positive charge leaves than enters, making the inside negative relative to the outside: a membrane potential [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('add5f177-be81-55cd-ade0-e128fe434315', '0939157e-2b6d-526f-9e81-f554572786ac', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('12f2617a-62be-5789-b905-cb1fd1e945f3', 'short', 'Explain why the uptake of glucose by sodium-dependent glucose cotransporters is described as indirect active transport.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('12f2617a-62be-5789-b905-cb1fd1e945f3', 'Na⁺ moves down its concentration gradient into the cell through the cotransporter [1]; glucose is carried with it against its own gradient [1]; ATP is not used by the cotransporter itself but by the sodium–potassium pump that keeps Na⁺ low inside the cell, so ATP is used indirectly [1].', 'Na⁺ moves down its concentration gradient into the cell through the cotransporter [1]; glucose is carried with it against its own gradient [1]; ATP is not used by the cotransporter itself but by the sodium–potassium pump that keeps Na⁺ low inside the cell, so ATP is used indirectly [1].', '[{"text": "Marking point 1", "any": ["sodium into", "sodium gradient"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["against its gradient", "up its gradient"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["sodium-potassium pump", "pump", "atp is used by the pump"], "all": [], "marks": 1}]'::jsonb, 'Na⁺ moves down its concentration gradient into the cell through the cotransporter [1]; glucose is carried with it against its own gradient [1]; ATP is not used by the cotransporter itself but by the sodium–potassium pump that keeps Na⁺ low inside the cell, so ATP is used indirectly [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('add5f177-be81-55cd-ade0-e128fe434315', '12f2617a-62be-5789-b905-cb1fd1e945f3', 27);
