insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('120c66f1-81e2-5cb2-b793-d3cab70e9c5f', 'Solute concentration is higher inside the cell than in distilled water, and the membrane is impermeable to the solutes [1]; water molecules move randomly both ways but more move into the cell, a net movement by osmosis (through aquaporins) [1]; the cell swells and bursts (lysis) because it has no cell wall [1].', 'Solute concentration is higher inside the cell than in distilled water, and the membrane is impermeable to the solutes [1]; water molecules move randomly both ways but more move into the cell, a net movement by osmosis (through aquaporins) [1]; the cell swells and bursts (lysis) because it has no cell wall [1].', '[{"text": "Marking point 1", "any": ["water moves in", "water enters", "gains water", "water flows in", "into the cell", "move into", "moves into", "enter"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["more solute inside", "higher concentration inside", "lower water potential inside", "concentrated inside", "higher inside", "concentration inside"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["burst", "lysis", "lyse", "swell"], "all": [], "marks": 1}]'::jsonb, 'Solute concentration is higher inside the cell than in distilled water, and the membrane is impermeable to the solutes [1]; water molecules move randomly both ways but more move into the cell, a net movement by osmosis (through aquaporins) [1]; the cell swells and bursts (lysis) because it has no cell wall [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('d551981e-b262-5e34-a8ac-0c5108f62502', '120c66f1-81e2-5cb2-b793-d3cab70e9c5f', 14);
