insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e3b70529-cdfd-588e-8af9-115614860787', 'short', 'Explain why plant cells do not burst in pure water but animal cells do.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e3b70529-cdfd-588e-8af9-115614860787', 'Plant cells have a strong cellulose cell wall [1]; as water enters, turgor pressure builds against the wall, which resists further expansion and stops bursting; animal cells have no wall, so they swell and lyse [1].', 'Plant cells have a strong cellulose cell wall [1]; as water enters, turgor pressure builds against the wall, which resists further expansion and stops bursting; animal cells have no wall, so they swell and lyse [1].', '[{"text": "Marking point 1", "any": ["cell wall", "wall"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["turgor", "pressure", "resists", "prevents"], "all": [], "marks": 1}]'::jsonb, 'Plant cells have a strong cellulose cell wall [1]; as water enters, turgor pressure builds against the wall, which resists further expansion and stops bursting; animal cells have no wall, so they swell and lyse [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('60034c64-54bc-567f-88d7-c51e75b94ef5', 'e3b70529-cdfd-588e-8af9-115614860787', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('382bfa9c-7c0e-599f-8b6c-25ec8a5e053c', 'short', 'Explain why organs for transplant are kept in isotonic solution.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('382bfa9c-7c0e-599f-8b6c-25ec8a5e053c', 'An isotonic solution has the same solute concentration as the cells, so there is no net water movement [1]; cells do not swell/burst or shrink, so the organ is not damaged [1].', 'An isotonic solution has the same solute concentration as the cells, so there is no net water movement [1]; cells do not swell/burst or shrink, so the organ is not damaged [1].', '[{"text": "Marking point 1", "any": ["isotonic", "same concentration", "no net"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["swell", "shrink", "damage", "burst"], "all": [], "marks": 1}]'::jsonb, 'An isotonic solution has the same solute concentration as the cells, so there is no net water movement [1]; cells do not swell/burst or shrink, so the organ is not damaged [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('60034c64-54bc-567f-88d7-c51e75b94ef5', '382bfa9c-7c0e-599f-8b6c-25ec8a5e053c', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c335fa03-8fe3-5a87-b733-500e7dc95f0d', 'short', 'Explain the role of the contractile vacuole in a freshwater protist.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c335fa03-8fe3-5a87-b733-500e7dc95f0d', 'Fresh water is hypotonic to the cytoplasm [1]; so water continually enters the cell by osmosis [1]; the contractile vacuole collects excess water and expels it (using ATP), preventing the cell from bursting [1].', 'Fresh water is hypotonic to the cytoplasm [1]; so water continually enters the cell by osmosis [1]; the contractile vacuole collects excess water and expels it (using ATP), preventing the cell from bursting [1].', '[{"text": "Marking point 1", "any": ["hypotonic", "fresh water", "lower solute"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["water enters", "osmosis", "into the cell"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["pump", "expel", "remove", "burst"], "all": [], "marks": 1}]'::jsonb, 'Fresh water is hypotonic to the cytoplasm [1]; so water continually enters the cell by osmosis [1]; the contractile vacuole collects excess water and expels it (using ATP), preventing the cell from bursting [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('60034c64-54bc-567f-88d7-c51e75b94ef5', 'c335fa03-8fe3-5a87-b733-500e7dc95f0d', 18);
