insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9b6efa6c-41b9-5464-8f1e-f579d84d2aca', 'short', 'Explain, using water potential, what happens to a plant cell placed in a hypertonic solution.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9b6efa6c-41b9-5464-8f1e-f579d84d2aca', 'The solution has a lower (more negative) water potential than the cell [1]; water leaves the cell by osmosis [1]; pressure potential falls to zero, the cell becomes flaccid and the membrane pulls away from the wall (plasmolysis) [1].', 'The solution has a lower (more negative) water potential than the cell [1]; water leaves the cell by osmosis [1]; pressure potential falls to zero, the cell becomes flaccid and the membrane pulls away from the wall (plasmolysis) [1].', '[{"text": "Marking point 1", "any": ["lower water potential", "more negative"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["water leaves", "out of the cell", "osmosis"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["pressure potential falls", "flaccid", "plasmolys"], "all": [], "marks": 1}]'::jsonb, 'The solution has a lower (more negative) water potential than the cell [1]; water leaves the cell by osmosis [1]; pressure potential falls to zero, the cell becomes flaccid and the membrane pulls away from the wall (plasmolysis) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('60034c64-54bc-567f-88d7-c51e75b94ef5', '9b6efa6c-41b9-5464-8f1e-f579d84d2aca', 26);
