insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d8d17d49-a3d8-5110-aec6-ce20ee01e11d', 'The partially negative oxygen of water is attracted to Na⁺ ions [1]; the partially positive hydrogens are attracted to Cl⁻ ions, so water molecules surround and separate the ions (solvation) [1].', 'The partially negative oxygen of water is attracted to Na⁺ ions [1]; the partially positive hydrogens are attracted to Cl⁻ ions, so water molecules surround and separate the ions (solvation) [1].', '[{"text": "Marking point 1", "any": ["δ- oxygen", "oxygen faces"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["hydrogen faces"], "all": [], "marks": 1}]'::jsonb, 'The partially negative oxygen of water is attracted to Na⁺ ions [1]; the partially positive hydrogens are attracted to Cl⁻ ions, so water molecules surround and separate the ions (solvation) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
